const all = $input.all();
if (all.length === 0) throw new Error('[Extraer Historial] Sin items');

const ctxNode = $('Code: Preparar Contexto');
const rawCtx = ctxNode.all().length > 0
  ? ctxNode.item.json
  : ($('Loop: Un envio a la vez').all().length > 0 ? $('Loop: Un envio a la vez').item.json : {});

const ctx = {
  shipping_code:            rawCtx.shipping_code,
  client_code:              rawCtx.client_code,
  client_name:              rawCtx.client_name,
  client_center_code:       rawCtx.client_center_code,
  client_references:        rawCtx.client_references,
  numero_pedido:            rawCtx.numero_pedido,
  shipping_status_code:     rawCtx.shipping_status_code,
  shipping_status_datetime: rawCtx.shipping_status_datetime,
  _docid:                   rawCtx._docid,
  fecha_procesado:          rawCtx.fecha_procesado,
  skip:                     rawCtx.skip,
  force_internal:           rawCtx.force_internal,
  is_2500:                  rawCtx.is_2500,
  numero_avisos:            rawCtx.numero_avisos,
  internal_email:           rawCtx.internal_email,
  gmail_credential_name:    rawCtx.gmail_credential_name,
  cca_zone:                 rawCtx.cca_zone,
};

const MAX_EVENTS = 20;

const bultos = [];
for (let i = 0; i < all.length; i++) {
  const httpResp = all[i].json;

  // Gestión de errores en la petición (si alwaysOutputData está activo)
  if (httpResp.error || !httpResp.data || !httpResp.data.shipping_history) {
    let fallbackCode = 'unknown';
    try {
      fallbackCode = $('Code: Expandir Bultos').input.all()[i].json.current_item_code;
    } catch (e) {
      fallbackCode = (ctx.shipping_code || 'envio') + '_err';
    }

    bultos.push({
      item_code: fallbackCode,
      history: 'ERROR: No se pudo obtener el historial (' + (httpResp.error?.message || '502 Bad Gateway') + ')',
      shipping_status_code: 'FETCH_ERROR'
    });
    continue;
  }

  const histData = httpResp.data.shipping_history;
  const item_code = histData.item_code || (httpResp.shipping_code ? httpResp.shipping_code : 'unknown');

  let rawEvents = [];
  if (histData.events) {
    rawEvents = histData.events;
  } else if (Array.isArray(histData)) {
    rawEvents = histData;
  } else if (httpResp.events) {
    rawEvents = httpResp.events;
  }

  const events = rawEvents.length <= MAX_EVENTS
    ? rawEvents
    : [rawEvents[0], ...rawEvents.slice(-(MAX_EVENTS - 1))];
  let latestEvent = null;
  const lines = [];

  for (let j = 0; j < events.length; j++) {
    const e = events[j];
    const raw_date = e.event_date || e.item_event_date || '';
    const date = raw_date ? raw_date.substring(0, 16).replace('T', ' ') : '????-??-?? ??:??';

    if (!latestEvent || raw_date > (latestEvent.event_date || latestEvent.item_event_date || '')) {
      latestEvent = e;
    }

    const code = e.code || e.event_code || '????';
    const desc = e.description || e.event_description || '';
    const detailRaw = (e.detail && e.detail.External_event_text) ? e.detail.External_event_text : ((e.detail && e.detail.item_event_text) ? e.detail.item_event_text : '');
    const cleanDetail = (detailRaw && detailRaw !== 'null' && detailRaw !== 'undefined') ? ' - ' + detailRaw : '';
    lines.push(date + ' | [' + code + '] ' + desc + cleanDetail);
  }

  bultos.push({
    item_code: item_code,
    history: lines.join('\n'),
    shipping_status_code: latestEvent ? String(latestEvent.code || latestEvent.event_code || '') : ''
  });
}

bultos.sort(function(a, b) { return a.item_code < b.item_code ? -1 : 1; });

return [{ json: Object.assign({}, ctx, { bultos: bultos }) }];

const client_code = String($('Code: Preparar Contexto').item.json.client_code || '').trim();
let access_token = '';

if (client_code === '47352') access_token = $('Token CTT SNAPPY').first().json.access_token;
else if (client_code === '48630') access_token = $('Token CTT HAMINOS').first().json.access_token;
else if (client_code === '47685') access_token = $('Token CTT MIESTERY').first().json.access_token;
else if (client_code === '45416') access_token = $('Token CTT KULTUDENDA').first().json.access_token;

if (!access_token) {
  throw new Error('Unknown client_code or missing token: ' + client_code);
}

return {
  ...$json,
  bearer_token: access_token
};

const TERMINAL = new Set(['2000', '2100', '2300', '2310', '3000']);

return $input.all()
  .filter(item => {
    const status = String(item.json.shipping_status_code || '').replace(/"/g, '').trim();
    if (!TERMINAL.has(status)) return true;
    const bultos = Array.isArray(item.json.items) ? item.json.items.length : 0;
    return bultos > 1;
  })
  .map(item => ({ json: item.json }));

// Determina skip, force_internal y numero_avisos a partir del doc Firestore
const firestoreDoc = $input.item.json;
const shipment = $('Loop: Un envío a la vez').item.json;
const hoy = $now.toFormat('yyyy-MM-dd');
const ayer = $now.minus({days: 1}).toFormat('yyyy-MM-dd');

shipment.client_references = shipment.client_references || ['sin-ref'];
const is2500 = String(shipment.shipping_status_code || '') === '2500';
const docValido = firestoreDoc?.numero_envio || firestoreDoc?.shipping_code;
const doc = docValido ? firestoreDoc : null;

// Normaliza fecha_procesado a YYYY-MM-DD independientemente del formato almacenado
function normalizeFecha(f) {
  if (!f) return '';
  const s = String(f).replace(/\"/g, '').substring(0, 10);
  // Detect legacy DD-MM-YYYY format
  if (/^\d{2}-\d{2}-\d{4}$/.test(s)) {
    const [d, m, y] = s.split('-');
    return `${y}-${m}-${d}`;
  }
  return s; // Already YYYY-MM-DD
}

let skip = false;
let force_internal = false;

// Saneamiento de numero_avisos (evita el bug de concatenación previo)
let raw_avisos = String(doc?.numero_avisos || 0).replace(/\"/g, '');
let numero_avisos = parseInt(raw_avisos) || 0;
if (numero_avisos > 100) {
  // Si el número es absurdamente alto (ej: 11116), probablemente está corrupto
  numero_avisos = raw_avisos.length; // Una aproximación razonable: contar cuántos reintentos hubo
}

if (doc) {
  const fecha = normalizeFecha(doc.fecha_procesado);
  const estado_actual = String(shipment.shipping_status_code || '');
  const estado_anterior = String(doc.estado || '');
  skip = !is2500 && fecha === hoy && estado_actual === estado_anterior;
  force_internal = !skip && (fecha === ayer || is2500);
} else {
  force_internal = is2500;
}

return {
  json: {
    ...shipment,
    _docid: (doc?._docid || shipment.shipping_code || '').toString().replace(/\"/g, ''),
    fecha_procesado: $now.toFormat('yyyy-MM-dd HH:mm:ss'),
    skip,
    force_internal,
    is_2500: is2500,
    numero_avisos
  }
};

// Expande 1 envío en N items (uno por bulto/item)
const shipment = $input.first().json;
const items = shipment.items || [];

if (items.length === 0) {
  return [{ json: { current_item_code: shipment.shipping_code + '001' } }];
}

return items.map(item => ({
  json: {
    current_item_code: item.item_code
  }
}));

const item   = $input.item.json;
const bultos = item.bultos || [];
const now    = new Date();

let manifest_hours   = 0;
let transit_hours    = 0;
let delivery_hours   = 0;
let stationary_hours = 0;
let last_event_date  = null;

bultos.forEach(b => {
  const historyStr = b.history || '';
  if (!historyStr) return;

  // Procesamos eventos de una vez sin split/map pesados
  const lines = historyStr.split('\n');
  const events = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!line) continue;
    const parts = line.split(' | ');
    if (parts.length < 2) continue;

    const d = new Date(parts[0]);
    if (isNaN(d.getTime())) continue;

    const match = parts[1].match(/\[(\d+)\]/);
    const code = match ? match[1] : null;
    events.push({ date: d, code });
  }

  if (events.length === 0) return;

  // Encontrar el último de cada tipo (recorriendo una sola vez al revés)
  let lManifest, lTransit, lDelivery, lStationary, latest;

  for (let i = events.length - 1; i >= 0; i--) {
    const e = events[i];
    if (!latest || e.date > (latest.date || 0)) latest = e;

    if (!lManifest && ['0000','0030'].includes(e.code)) lManifest = e;
    if (!lTransit && ['0900','1000'].includes(e.code)) lTransit = e;
    if (!lDelivery && ['1200','1500','1600','2400','2600','2700'].includes(e.code)) lDelivery = e;
    if (!lStationary && ['1700','1800'].includes(e.code)) lStationary = e;
  }

  if (latest && (!last_event_date || latest.date > last_event_date)) last_event_date = latest.date;

  const diffNow = (d) => d ? (now - d) / 3600000 : 0;
  if (lManifest)   manifest_hours   = Math.max(manifest_hours,   diffNow(lManifest.date));
  if (lTransit)    transit_hours    = Math.max(transit_hours,    diffNow(lTransit.date));
  if (lDelivery)   delivery_hours   = Math.max(delivery_hours,   diffNow(lDelivery.date));
  if (lStationary) stationary_hours = Math.max(stationary_hours, diffNow(lStationary.date));
});

return {
  json: {
    ...item,
    manifest_hours:   Number(manifest_hours.toFixed(1)),
    transit_hours:    Number(transit_hours.toFixed(1)),
    delivery_hours:   Number(delivery_hours.toFixed(1)),
    stationary_hours: Number(stationary_hours.toFixed(1)),
    h_en_estado: last_event_date ? Number(((now - last_event_date) / 3600000).toFixed(1)) : 0
  }
};

// Detecta incidencia activa: 1600/2400/2600/2700/0600 sin resolución posterior (1500/2000/2100)
const INCIDENT_CODES   = new Set(['1600','2400','2600','2700','0600']);
const RESOLUTION_CODES = new Set(['1500','2000','2100']);
const item = $input.item.json;

let has_active_incident  = false;
let active_incident_code = null;

for (const b of (item.bultos || [])) {
  const lines = (b.history || '').split('\n').filter(Boolean);
  const evts  = lines.map(l => {
    const parts = l.split(' | ');
    const m     = parts[1]?.match(/\[(\w+)\]/);
    return m ? m[1] : null;
  }).filter(Boolean);

  let lastIncident = null;
  for (const code of evts) {
    if (INCIDENT_CODES.has(code))   lastIncident = code;
    if (RESOLUTION_CODES.has(code)) lastIncident = null;
  }
  if (lastIncident) {
    has_active_incident  = true;
    active_incident_code = lastIncident;
    break;
  }
}

return { json: { ...item, has_active_incident, active_incident_code } };

const TERMINAL = new Set(['2000', '2100', '2300', '2310', '3000']);
const item = $input.item.json;
const bultos = item.bultos || [];

if (bultos.length === 0) return { json: { ...item, skip_final: false } };

const allTerminal = bultos.every(b => {
  const code = String(b.shipping_status_code || '').replace(/"/g, '').trim();
  return TERMINAL.has(code);
});

return { json: { ...item, skip_final: allTerminal } };

