parameters.jsCode:
const raw = $input.item.json;
const ctx = $('Code: Extraer Historial').item.json;
const sla = $('Code: Calcular SLA Horas').item.json;

const formatted_history = (ctx.bultos || []).map(b => 'Item: ' + b.item_code + '\n' + b.history).join('\n\n---\n\n');
const bultos_raw = JSON.stringify(ctx.bultos || []);

// --- Parsear respuesta IA ---
const aiText = raw.output?.[0]?.content?.[0]?.text || '{}';
let ai;
try {
  ai = JSON.parse(aiText.replace(/```json|```/g, '').trim());
} catch (e) {
  ai = {
    analysis: { ultimo_estado: '', item_afectado: null, justificacion: 'parse_error: ' + e.message },
    decision: { is_incident: false, should_notify: false, notification_type: 'none' }
  };
}

let is_incident       = ai.decision?.is_incident   === true;
let should_notify     = ai.decision?.should_notify === true;
let notification_type = ai.decision?.notification_type || 'none';

// --- Estado actual desde historial ---
let estado_actual = String((ctx.bultos && ctx.bultos[0]) ? ctx.bultos[0].shipping_status_code : (ctx.shipping_status_code || '')).replace(/["']/g, '').trim();

// --- Override matemático SLA (usa 'sla' para hours e incidencias) ---
const isManifest   = estado_actual === '0000' || estado_actual === '0030';
const isTransit    = estado_actual === '0900' || estado_actual === '1000';
const isDelivery   = ['1500','1600','2400','2600','2700'].includes(estado_actual);
const isDelegacionDestino = estado_actual === '1200'; // hito normal, umbral más alto (48h)
const isStationary = estado_actual === '1700' || estado_actual === '1800';
const is2500       = estado_actual === '2500';
const is71INAT     = estado_actual === '71_INAT';

// force_internal solo aplica si el estado sigue siendo problemático (no en hitos normales)
const stateIsStillProblematic = isDelivery || isStationary || is2500 || is71INAT || sla.has_active_incident;
if ((ctx.force_internal === true && stateIsStillProblematic) || sla.has_active_incident ||
  (isManifest   && (parseFloat(sla.manifest_hours)   || 0) > 24) ||
  (isTransit    && (parseFloat(sla.transit_hours)    || 0) > 24) ||
  (isDelivery   && (parseFloat(sla.delivery_hours)   || 0) > 24) ||
  (isDelegacionDestino && (parseFloat(sla.delivery_hours) || 0) > 48) ||
  (isStationary && (parseFloat(sla.stationary_hours) || 0) > 24) ||
  is71INAT
) {
  is_incident   = true;
  should_notify = true;
  if (notification_type === 'none') {
    if (sla.has_active_incident) {
      const ac = sla.active_incident_code;
      notification_type = ac === '0600' ? 'recogida_fallida' : 'segundo_intento';
    } else if (isManifest) {
      notification_type = estado_actual === '0030' ? 'recogida_0030' : 'pendiente';
    } else if (isTransit)    notification_type = 'agilizar_transito';
    else if (is2500)         notification_type = 'devolucion';
    else if (is71INAT)       notification_type = 'agilizar_reparto';
    else if (isDelivery || isStationary || isDelegacionDestino) notification_type = 'agilizar_reparto';
  }
}

return {
  json: {
    ...ctx,
    shipping_status_code: estado_actual || ctx.shipping_status_code,
    formatted_history,
    bultos_raw,
    is_incident,
    should_notify,
    notification_type,
    ai_justification: ai.analysis?.justificacion || '',
    affected_bulto:   ai.analysis?.item_afectado || null
  }
};

const raw = $input.item.json;
const SEG = raw.shipping_code;
const PED = raw.numero_pedido || (raw.client_references && raw.client_references[0]) || '';

const TEMPLATES = {
  pendiente:         { subject: 'ALERTA PENDIENTE (0000)',                                     body: 'Hola, se ha detectado que el siguiente envío lleva más de 24 horas en estado 0000. Por favor, revisadlo.\nPEDIDO: - ' + (PED || SEG) },
  devolucion:        { subject: 'Devolución en proceso: ' + (PED || SEG),                        body: 'Hola, el siguiente pedido ha entrado en proceso de devolución. Iniciamos seguimiento manual.\nCÓDIGO: - ' + SEG },
  siniestro:         { subject: 'Apertura de siniestro: ' + (PED || SEG),                        body: 'Buenos días CTT, solicitamos la apertura oficial de expediente de siniestro por pérdida/daño para el envío:\nREFERENCIA: - ' + SEG + '. Quedamos a la espera del número de expediente.' },
  segundo_intento:   { subject: 'Incidencia en el envío ' + (PED || SEG),                        body: 'Buenos días. Tras la incidencia en el primer intento, solicitamos automáticamente un segundo intento de reparto para el siguiente día hábil.\nEXPEDICIÓN: - ' + SEG + '. Gracias.' },
  recogida_fallida:  { subject: 'Incidencia en el envío ' + (PED || SEG),                        body: 'Buenos días. Solicitamos que se reintente la recogida fallida del siguiente envío:\nEXPEDICIÓN: - ' + SEG + '. Gracias.' },
  agilizar_transito: { subject: 'Incidencia en el envío ' + (PED || SEG),                        body: 'Buenos días. El envío ' + SEG + ' lleva más de 24 horas en tránsito sin pasar a reparto. Solicitamos que salga a reparto el próximo día hábil. Gracias.' },
  agilizar_reparto:  { subject: 'Incidencia en el envío ' + (PED || SEG),                        body: 'Buenos días. El envío ' + SEG + ' lleva más de 24 horas en reparto sin entregarse. Solicitamos que sea sacado nuevamente a reparto hoy mismo. Gracias.' },
  punto_ctt:         { subject: 'Envío en punto CTT: ' + (PED || SEG),                           body: 'Buenos días. Necesitamos la dirección detallada del punto de recogida para el siguiente envío:\nEXPEDICIÓN: - ' + SEG + '. Gracias de antemano.' },
  recogida_0030:     { subject: 'Incidencia en el envío ' + (PED || SEG),                        body: 'Buenos días. Solicitamos agilizar la recogida del siguiente envío que lleva más de 24 horas pendiente:\nLISTADO DE ENVÍOS: - ' + SEG + '. Gracias.' },
};

let res = { ...raw, asunto: '', cuerpo: '', target_type: 'none', destinatario: '', incidencia: '', razon: '', email_subject: '', email_body: '', to_email: '' };

const active = raw.sigue_incidencia === true || raw.is_incident === true || raw.should_notify === true;

if (active) {
  const cat = (raw.notification_type || raw.categoria || raw.decision || 'Otros').toLowerCase();

  if (cat.includes('reparto_estancado') || cat.includes('agilizar_reparto')) { 
    res.target_type = 'standard'; res.asunto = TEMPLATES.agilizar_reparto.subject; res.cuerpo = TEMPLATES.agilizar_reparto.body; 
  }
  else if (cat.includes('transito_estancado') || cat.includes('agilizar_transito')) { 
    res.target_type = 'standard'; res.asunto = TEMPLATES.agilizar_transito.subject; res.cuerpo = TEMPLATES.agilizar_transito.body; 
  }
  else if (cat.includes('segundo_intento') || cat.includes('fallo reparto')) { 
    res.target_type = 'standard'; res.asunto = TEMPLATES.segundo_intento.subject; res.cuerpo = TEMPLATES.segundo_intento.body; 
  }
  else if (cat.includes('punto_ctt') || cat.includes('pudo') || cat.includes('2300') || cat.includes('2310')) { 
    res.target_type = 'standard'; res.asunto = TEMPLATES.punto_ctt.subject; res.cuerpo = TEMPLATES.punto_ctt.body; 
  }
  else if (cat.includes('recogida_fallida') || cat.includes('0600')) {
    res.target_type = 'standard'; res.asunto = TEMPLATES.recogida_fallida.subject; res.cuerpo = TEMPLATES.recogida_fallida.body;
  }
  else if (cat.includes('pendiente') || cat.includes('0000')) { 
    res.target_type = 'internal'; res.asunto = TEMPLATES.pendiente.subject; res.cuerpo = TEMPLATES.pendiente.body; 
  }
  else if (cat.includes('recogida_0030') || cat.includes('0030')) {
    res.target_type = 'standard'; res.asunto = TEMPLATES.recogida_0030.subject; res.cuerpo = TEMPLATES.recogida_0030.body;
  }
  else if (cat.includes('devolucion') || cat.includes('2500')) { 
    res.target_type = 'internal'; res.asunto = TEMPLATES.devolucion.subject; res.cuerpo = TEMPLATES.devolucion.body; 
  }
  else if (cat.includes('siniestro') || cat.includes('6_inct') || cat.includes('1006') || cat.includes('1008') || cat.includes('1012')) { 
    res.target_type = 'internal'; res.asunto = TEMPLATES.siniestro.subject; res.cuerpo = TEMPLATES.siniestro.body; 
  }
  else {
    res.target_type = 'internal';
    res.asunto = 'Gestión Urgente: ' + SEG;
    res.cuerpo = 'Hola, se requiere revisión manual para el envío ' + SEG + '.\nJustificación: ' + (raw.justificacion || raw.justification || raw.ai_justification || 'Sin detalle');
  }

  res.incidencia = res.asunto;
  res.razon = raw.ai_justification || raw.justificacion || raw.justification || 'Análisis IA completado';

  res.email_subject = res.asunto;
  res.email_body = res.cuerpo;

  const avisos = parseInt(raw.numero_avisos) || 0;
  res.numero_avisos = avisos + 1;

  if (avisos > 0 && res.target_type === 'standard') {
    res.target_type = 'internal';
    res.asunto = '[RE-INCIDENCIA] ' + res.asunto;
    res.cuerpo = 'Hola equipo, este envío ya fue notificado previamente y sigue en incidencia. Por favor, gestionad manualmente.\n\n' + res.cuerpo;
    res.email_subject = res.asunto;
    res.email_body = res.cuerpo;
  }

  if (res.target_type === 'internal') {
    res.destinatario = raw.internal_email || 'incidenciasamzdiscounts01@gmail.com';
  } else if (res.target_type === 'standard') {
    res.destinatario = raw.cca_zone || 'cca.z3@cttexpress.com';
  }
  res.to_email = res.destinatario;
}

if (active && !res.asunto) {
  res.target_type = 'internal';
  res.asunto = 'Gestión Urgente: ' + SEG;
  res.cuerpo = 'Hola, se requiere revisión manual para el envío ' + SEG + '.\nJustificación: ' + (raw.ai_justification || raw.justificacion || 'Sin detalle');
  res.email_subject = res.asunto;
  res.email_body = res.cuerpo;
  res.destinatario = raw.internal_email || 'incidenciasamzdiscounts01@gmail.com';
  res.to_email = res.destinatario;
}

res.force_internal = (res.target_type === 'internal');


return res;

let ia = {};
let sla = {};
let ctx = {};

try { ia = $('Code: Procesar Respuesta IA').item.json; } catch (e) {}
try { sla = $('Code: Calcular SLA Horas').item.json; } catch (e) {}
try { ctx = $('Code: Preparar Contexto').item.json; } catch (e) {}

const base = $input.item.json || ctx;

return {
  json: {
    _docid: ('' + (ia._docid || base._docid || base.shipping_code || '')).replace(/\"/g, ''),
